<script>
    document.addEventListener('DOMContentLoaded', function() {
        const mobileMenuButton = document.getElementById('mobile-menu-button');
        const mobileMenu = document.getElementById('mobile-menu');
        const mobileOverlay = document.getElementById('mobile-overlay');
        const mobileCloseButton = document.getElementById('mobile-close-button');

        // Toggle mobile menu
        function toggleMobileMenu() {
            mobileMenu.classList.toggle('translate-x-0');
            mobileMenu.classList.toggle('translate-x-full');
            mobileOverlay.classList.toggle('hidden');
            document.body.classList.toggle('overflow-hidden');

            // Toggle aria-expanded for accessibility
            const isExpanded = mobileMenu.classList.contains('translate-x-0');
            mobileMenuButton.setAttribute('aria-expanded', isExpanded);
        }

        // Open menu when clicking the menu button
        if (mobileMenuButton) {
            mobileMenuButton.addEventListener('click', toggleMobileMenu);
        }

        // Close menu when clicking the close button
        if (mobileCloseButton) {
            mobileCloseButton.addEventListener('click', toggleMobileMenu);
        }

        // Close menu when clicking the overlay
        if (mobileOverlay) {
            mobileOverlay.addEventListener('click', toggleMobileMenu);
        }

        // Close menu when clicking on a link
        if (mobileMenu) {
            const mobileLinks = mobileMenu.querySelectorAll('a, button[type="submit"]');
            mobileLinks.forEach(link => {
                link.addEventListener('click', () => {
                    if (window.innerWidth < 1024) { // Only on mobile/tablet
                        toggleMobileMenu();
                    }
                });
            });
        }

        // Close menu when pressing Escape key
        document.addEventListener('keydown', (e) => {
            if (e.key === 'Escape' && mobileMenu && !mobileMenu.classList.contains('translate-x-full')) {
                toggleMobileMenu();
            }
        });

        // Close menu when window is resized to desktop
        function handleResize() {
            if (window.innerWidth >= 1024 && mobileMenu && !mobileMenu.classList.contains('translate-x-full')) {
                toggleMobileMenu();
            }
        }

        window.addEventListener('resize', handleResize);
    });
</script>



